def get_group_short_name(group: QgsLayerTreeGroup) -&gt; str:
    if group.customProperty("wmsShortName"):
        return group.customProperty("wmsShortName")
    elif hasattr(group, "groupLayer"):  # noqa: SIM102
        # since QGIS 3.38
        if (
            group.groupLayer()
